#!/usr/bin/env node
// Patches .output/server to replace @tanstack/router-core with the version
// that the SSR bundle was compiled against (1.120.19, which exports `pick`).
import { readFileSync, writeFileSync, existsSync, cpSync, rmSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath } from "node:url";

const outputDir = fileURLToPath(new URL("../.output/server", import.meta.url));
const pkgPath = join(outputDir, "package.json");

if (!existsSync(pkgPath)) {
  console.log("No .output/server/package.json found — skipping patch");
  process.exit(0);
}

// 1. Patch package.json
const pkg = JSON.parse(readFileSync(pkgPath, "utf8"));
pkg.dependencies["@tanstack/router-core"] = "1.120.19";
writeFileSync(pkgPath, JSON.stringify(pkg, null, 2));
console.log("Patched .output/server/package.json: @tanstack/router-core => 1.120.19");

// 2. Replace the installed router-core with the compatible version
const installedCoreDir = join(outputDir, "node_modules/@tanstack/router-core");
const nitroCompatDir = join(outputDir, "node_modules/.nitro/@tanstack/router-core@1.120.19");

if (existsSync(nitroCompatDir) && existsSync(installedCoreDir)) {
  rmSync(installedCoreDir, { recursive: true, force: true });
  cpSync(nitroCompatDir, installedCoreDir, { recursive: true });
  console.log("Replaced node_modules/@tanstack/router-core with 1.120.19 from .nitro cache");
} else {
  console.log(`Note: nitroCompatDir exists=${existsSync(nitroCompatDir)}, installedCoreDir exists=${existsSync(installedCoreDir)}`);
}

